/**
 * STOP THE SYNCHRONIZED PRESENTATION
 *
 * This macro ends the active shared session and closes the shared terminal
 * for its participants. It does not delete any Journal, page, or setting.
 * There is nothing to configure.
 */

// ── CONFIGURATION ─────────────────────────────────────────────
// None: this macro acts on the active presentation.
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("This macro is for the GM only.");
const api = game.modules.get("retro-crt-terminal")?.api;
if (!api) return ui.notifications.error("Retro CRT Terminal is not active.");
if (!api.shared.state?.active) return ui.notifications.warn("No synchronized presentation is active.");

await api.shared.stop();
ui.notifications.info("Synchronized presentation stopped.");
